  <div class="writer-head"><div><span class="muted">Editorial campaign · post-<?=intval($post['id'])?></span><h1><?=e($post['title'])?></h1></div><a class="wbtn" href="<?=url('/write/campaigns')?>">All campaigns</a></div>
  <?php foreach(flashes()as$f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['message'])?></div><?php endforeach;?>
  <div class="settings-grid">
